// Des: Tests for routines: plan, approve, wait, park, unsafe stop
// Flo: build a routine > run it in the rig > check item states, alerts, records
// I/O: none (mock site on loopback, scratch profile) > pass or fail (skips without Chrome)
// Run: cd E:\zz-base-home\as-apps\in-inte\zr-zrow-webs && zig build test -Dfile=ru-flow-queu-test.zig
// ===================================================================
const std = @import("std"); const rigz = @import("te-rigz-brow.zig"); const task = @import("ru-task-runn.zig"); const queu = @import("ru-flow-queu.zig"); const appr = @import("ru-appr-list.zig"); const wait = @import("ru-wait-hand.zig"); const cfgz = @import("cf-conf-load.zig");
fn setup(rig: *rigz.Rig) !task.Ctx { rig.conf.noti_chai_orde = &.{"file"}; rig.conf.capz_acce_dayz = 99; rig.conf.capz_data_dayz = 99; rig.conf.capz_help_dayz = 99; var cx = rig.ctx(.live); cx.statd = try std.fmt.allocPrint(cx.aren, ".zig-cache/tmp/{s}", .{rig.tmpz.sub_path}); return cx; }
fn alerts(rig: *rigz.Rig, cx: *task.Ctx) ![]u8 { const pth = try std.fmt.allocPrint(cx.aren, "{s}/alerts.txt", .{cx.statd}); return std.Io.Dir.cwd().readFileAlloc(rig.iozz, pth, cx.aren, .limited(1 << 16)) catch return try cx.aren.dupe(u8, ""); }
const REFS_RISK = [_]cfgz.JobRef{ .{ .job = "usage-view" }, .{ .job = "key-revoke" }, .{ .job = "feedback-send", .text = "hello flow" } };
test "plan marks the risky item, unapproved risky items are skipped and never block the rest" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = try setup(&rig); const fid = try queu.create(&cx, "morning", &REFS_RISK); try std.testing.expectEqual(@as(u32, 1), try appr.show(&cx, fid)); const res = try queu.runFlow(&cx, fid); try std.testing.expectEqual(@as(u32, 2), res.done); try std.testing.expectEqual(@as(u32, 1), res.skip); try std.testing.expect(rig.waitPre("btn|Send|", 4000)); try std.testing.expect(!rig.hasRec("btn|Delete key")); }
test "approve once (double approve = once), rerun does only the pending row" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = try setup(&rig); const fid = try queu.create(&cx, "morning", &REFS_RISK); _ = try queu.runFlow(&cx, fid); const flw = try rig.store.itemList(cx.aren, fid); try std.testing.expectEqualStrings("skip", flw[1].st); try rig.store.itemSet(flw[1].id, "todo", "", 1); try std.testing.expectEqual(@as(i64, 1), try appr.setAppr(&cx, fid, "all", 1)); try std.testing.expectEqual(@as(i64, 0), try appr.setAppr(&cx, fid, "all", 1)); const res3 = try queu.runFlow(&cx, fid); try std.testing.expectEqual(@as(u32, 1), res3.done); try std.testing.expect(rig.waitPre("btn|Delete|", 4000)); }
test "needs-you: waits while the owner clears the check, then resumes the same item by itself, cool pace on" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.wait_maxx_secs = 25; var cx = try setup(&rig); const refs = [_]cfgz.JobRef{.{ .job = "page-open", .url = "/solving" }}; const fid = try queu.create(&cx, "one", &refs); const res = try queu.runFlow(&cx, fid); try std.testing.expectEqual(@as(u32, 1), res.done); try std.testing.expectEqualStrings("done", res.state); const flw = (try rig.store.flowGet(cx.aren, fid)).?; try std.testing.expectEqual(@as(i64, 1), flw.ivn); try std.testing.expect(flw.wms > 500); try std.testing.expectEqualStrings("done", flw.st); const al = try alerts(&rig, &cx); try std.testing.expect(std.mem.find(u8, al, "zr needs you") != null); try std.testing.expect(task.coolOn(&cx)); }
test "deadline parks the flow; a later run resumes at the waiting item" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.wait_maxx_secs = 1; var cx = try setup(&rig); const refs = [_]cfgz.JobRef{.{ .job = "page-open", .url = "/solving" }}; const fid = try queu.create(&cx, "one", &refs); const res = try queu.runFlow(&cx, fid); try std.testing.expectEqualStrings("park", res.state); const items = try rig.store.itemList(cx.aren, fid); try std.testing.expectEqualStrings("wait", items[0].st); const al = try alerts(&rig, &cx); try std.testing.expect(std.mem.find(u8, al, "waited too long") != null); std.Io.sleep(rig.iozz, .fromMilliseconds(2500), .awake) catch {}; const res2 = try queu.runFlow(&cx, fid); try std.testing.expectEqual(@as(u32, 1), res2.done); }
test "unsafe page stops the whole flow, rests 24 h, resume clears it" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = try setup(&rig); const refs = [_]cfgz.JobRef{ .{ .job = "page-open", .url = "/blocked" }, .{ .job = "feedback-send", .text = "after" } }; const fid = try queu.create(&cx, "two", &refs); const res = try queu.runFlow(&cx, fid); try std.testing.expectEqualStrings("stop", res.state); try std.testing.expectEqual(@as(u32, 0), res.done); try std.testing.expect(!rig.hasRec("btn|Send|")); try std.testing.expect(wait.unsafeUntil(&cx) > wait.realMs(rig.iozz)); const al = try alerts(&rig, &cx); try std.testing.expect(std.mem.find(u8, al, "keep your account safe") != null); const refs2 = [_]cfgz.JobRef{.{ .job = "usage-view" }}; const f2 = try queu.create(&cx, "later", &refs2); try std.testing.expectError(error.Unsafe, queu.runFlow(&cx, f2)); try rig.store.metaSet("unsafe_until", 0); const r2 = try queu.runFlow(&cx, f2); try std.testing.expectEqual(@as(u32, 1), r2.done); }
test "a 2nd challenge within 24 h is treated as unsafe" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = try setup(&rig); try rig.store.logAdd("halt", "captcha", false, wait.realMs(rig.iozz) - 3600000); const refs = [_]cfgz.JobRef{.{ .job = "page-open", .url = "/captcha" }}; const fid = try queu.create(&cx, "one", &refs); const res = try queu.runFlow(&cx, fid); try std.testing.expectEqualStrings("stop", res.state); try std.testing.expect(wait.unsafeUntil(&cx) > 0); }
test "dry-run previews every item and changes nothing; no consent = refused" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = try setup(&rig); const fid = try queu.create(&cx, "morning", &REFS_RISK); cx.mode = .dry; const res = try queu.runFlow(&cx, fid); try std.testing.expectEqual(@as(u32, 3), res.done); try std.testing.expectEqual(@as(usize, 0), rig.mock.recCnt()); try rig.store.metaSet("consent", 0); cx.mode = .live; try std.testing.expectError(error.NoConsent, queu.runFlow(&cx, fid)); }
test "item failures park only that item: a bad item does not stop the next one" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = try setup(&rig); const refs = [_]cfgz.JobRef{ .{ .job = "verify-email" }, .{ .job = "feedback-send", .text = "still runs" } }; const fid = try queu.create(&cx, "mixed", &refs); const res = try queu.runFlow(&cx, fid); try std.testing.expectEqual(@as(u32, 1), res.done); try std.testing.expectEqual(@as(u32, 1), res.fail); try std.testing.expectEqualStrings("done", res.state); try std.testing.expect(rig.waitPre("btn|Send|", 4000)); const al = try alerts(&rig, &cx); try std.testing.expect(std.mem.find(u8, al, "1 done, 1 need you") != null); }
test "routines come from config and unknown jobs or names are refused" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const conf = try cfgz.confParse(aren.allocator(), "{\"flow_list\":[{\"name\":\"morning\",\"jobs\":[{\"job\":\"signup\"},{\"job\":\"login\"}]}]}"); try std.testing.expectEqual(@as(usize, 2), queu.find(conf, "morning").?.jobs.len); try std.testing.expect(queu.find(conf, "nope") == null); try std.testing.expectError(error.BadConfig, cfgz.confParse(aren.allocator(), "{\"flow_list\":[{\"name\":\"\",\"jobs\":[{\"job\":\"login\"}]}]}")); var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = try setup(&rig); const bad = [_]cfgz.JobRef{.{ .job = "no-such-job" }}; try std.testing.expectError(error.NoJob, queu.create(&cx, "x", &bad)); try std.testing.expectError(error.BadFlow, queu.create(&cx, "x", &.{})); }
test "alerts never carry the typed private text" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.wait_maxx_secs = 25; var cx = try setup(&rig); const refs = [_]cfgz.JobRef{.{ .job = "page-open", .url = "/solving", .text = "secret words" }}; const fid = try queu.create(&cx, "one", &refs); _ = try queu.runFlow(&cx, fid); const al = try alerts(&rig, &cx); try std.testing.expect(std.mem.find(u8, al, "zr needs you") != null); try std.testing.expect(std.mem.find(u8, al, "secret") == null); }
test "a routine item can be limited to one account: other accounts skip it; nothing left for this account fails with BadFlow" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = try setup(&rig); cx.acct = "team1"; const refs = [_]cfgz.JobRef{ .{ .job = "usage-view", .acct = "team2" }, .{ .job = "key-revoke" }, .{ .job = "usage-view", .acct = "team1" } }; const fid = try queu.create(&cx, "mine", &refs); const items = try cx.store.itemList(cx.aren, fid); try std.testing.expectEqual(@as(usize, 2), items.len); try std.testing.expectEqualStrings("key-revoke", items[0].job); try std.testing.expectEqual(@as(i64, 1), items[0].seq); try std.testing.expectEqual(@as(i64, 2), items[1].seq); cx.acct = "team3"; const only = [_]cfgz.JobRef{.{ .job = "usage-view", .acct = "team2" }}; try std.testing.expectError(error.BadFlow, queu.create(&cx, "none", &only)); }
